import{t as e}from"./utils-COoNfFoj.js";var t={slug:`jahnavi-shah-tripsync`,influencerName:`Jahnavi Shah`,influencerHandle:`@jahnshah`,influencerAvatarUrl:`${e}/jahnavi-shah-tripsync-avatar.jpg`,heroDescription:`I am going on my dream vacation, but I'm also meeting a lot of family and friends, and the trip got extended for work. I kept re-planning my trip and coordinating with my family, friends, and work, which became very chaotic. I created an app with my live itinerary and a place where people can request to join or suggest new plans, so everyone's aware of what I'm doing that day and whether I'm free or not.`,assetTitle:`TripSync`,screenshotUrl:`${e}/jahnavi-shah-tripsync.png`,remixUrl:`https://www.perplexity.ai/computer/a/tripsync-Sfl1jGqBQH2iQv04UKJ_Hg`,promptTitle:`Try Jahnavi's Prompt`,promptText:`You are a senior product engineer, product manager, and UX designer helping build a mobile-first app called TripSync. The goal is to help solo travelers share itineraries and coordinate plans with friends through a social layer around the host’s trip. Friends can view plans, request to join activities, suggest ideas, and see who else is attending. Roles: Host (owns trip) and Guests (view and join plans). Build in two phases. MVP features: itinerary timeline with activity details (title, flexible time, location, notes, status: Open/Private/Solo), join request system with approvals and attendee lists, open time slots for suggestions, visibility into itineraries and attendees, and basic AI recommendations based on location and free time. MVP requirements: React/Next.js with Firebase or Supabase, Google login only, simple database, mobile-first UI inspired by Notion and Airbnb. Output architecture, database schemas (Users, Trips, Activities, JoinRequests, Attendees), APIs, components, and flows for creating trips, adding activities, and managing requests. V1 features: weather and travel-time context, AI recommendations, map view with route optimization, notifications, guest preferences, meetup suggestions, host controls (solo days, limits, auto-approvals), and optional location sharing. Include updated architecture, schema changes, integrations, AI prompts, and scaling considerations. UX should be intuitive, minimal-click, and clearly show who is joining what. Structure output as: MVP Architecture, Schema, APIs & Logic, UI Components, V1 Enhancements, AI Design, Tech Stack. Keep it practical and fast to build.`};export{t as default};
